def check_unused_assignments(node):
    assigned_to = node.find_children(lambda n: n.name == 'target')
    if len(assigned_to) == 0:
        return True
    for statement in node.find_descendants(lambda n: n.name == 'expression_statement'):
        if statement.find_descendants(lambda n: n.name == 'assign' and n.target not in assigned_to):
            return True
    return False
